            try:
                assignments[name] = int(value)
            except ValueError:
                try:
                    assignments[name] = float(value)
                except ValueError:
                    raise ValueError(f"Invalid numeric value: {value}")
    return assignments

def evaluate_expression(expr, assignments):
    try:
        # Replace variable names with their values
        for name in assignments:
            expr = expr.replace(name, str(assignments[name]))
        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, assignments)
    except Exception as e:
        raise ValueError(f"Failed to evaluate expression: {expr}")

def render_template(template_path, assignments):
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except IOError:
        raise IOError(f"Cannot read template file: {template_path}")

    output = []
    i = 0
    n = len(content)
    while i < n:
        if content.startswith('{{', i):
            j = content.find('}}', i)
            if j == -1:
                raise ValueError(f"Unclosed placeholder: {content[i:]}")
            placeholder = content[i+2:j]
            try:
                value = evaluate_expression(placeholder, assignments)
                # Format the value according to rules
                if isinstance(value, int):
                    output.append(str(value))
                else:
                    output.append(str(value))
            except ValueError as e:
                raise ValueError(f"Failed to evaluate placeholder: {content[i:j+2]}")
            i = j + 2
        else:
            output.append(content[i])
            i += 1
    return ''.join(output)

