import sys
import re
import os

def read_template(template_path):
    try:
        with open(template_path, 'r', encoding='utf-8') as f:
            return f.read()
    except IOError as e:
        print(f"error: {template_path}", file=sys.stderr)
        sys.exit(1)

def parse_assignments():
    assignments = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            name, value = line.split('=', 1)
            name = name.strip()
            value = value.strip()
            assignments[name] = int(value) if '.' not in value else float(value)
        except ValueError:
            print(f"error: {line}", file=sys.stderr)
            sys.exit(1)
    return assignments

def evaluate_expression(expr, variables):
    try:
        return eval(expr, {'__builtins__': None}, variables)
    except Exception as e:
        print(f"error: {expr}", file=sys.stderr)
        sys.exit(1)

def process_template(template, assignments):
    output = []
    i = 0
    n = len(template)
    while i < n:
        if template[i] == '{':
            if i + 1 >= n or template[i + 1] != '{':
                output.append(template[i])
                i += 1
                continue
            j = i + 2
            while j < n and template[j] != '}':
                j += 1
            if j >= n:
                output.append(template[i:])
                break
            expr = template[i+2:j]
            value = evaluate_expression(expr, assignments)
            output.append(str(value))
            i = j + 1
        else:
            output.append(template[i])
            i += 1
    return ''.join(output)

def main():
    template_path = sys.stdin.readline().strip()
    template = read_template(template_path)
    assignments = parse_assignments()
    result = process_template(template, assignments)
    print(result)

if __name__ == "__main__":
    main()
